using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
namespace LWS.TruckCheeseRolling.Editor {
public static class CheeseSceneryAuthoring {
 const string Root="Assets/TruckCheeseRolling/";
 static Material Material(string name,Color color,Texture texture=null){string path=Root+"Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.color=color;mat.mainTexture=texture;mat.enableInstancing=true;return mat;}
 public static void Create(CheeseMatch m){var root=new GameObject("Seeded hill scenery pool");var s=root.AddComponent<CheeseScenery>();m.scenery=s;s.terrain=m.weather.terrain;s.trees=new CheeseTree[14];s.props=new Transform[40];s.radii=new float[40];var tree=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Tree_03.prefab");var rock=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Toon Gas Station/Prefabs/Rock_Cluster_1A.prefab");var wolf=Animal("Wolf",Root+"Art/Animals/WolfLite.fbx",new Color(.5f,.55f,.61f),null);var cat=Animal("Cat",Root+"Art/Animals/MalbersCat.fbx",Color.white,AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Art/Animals/CatOrange.png"));
  for(int i=0;i<40;i++){var g=new GameObject(i<14?"Random tree "+i:i<32?"Random rock "+i:i%2==0?"Random wolf "+i:"Random cat "+i);g.transform.SetParent(root.transform,false);s.props[i]=g.transform;s.radii[i]=i<14?.8f:i<32?1.6f:1.4f;var source=i<14?tree:i<32?rock:i%2==0?wolf:cat;if(source==null)throw new Exception("Scenery source missing "+g.name);var visual=UnityEngine.Object.Instantiate(source,g.transform);visual.name="Vendor model visual";foreach(var c in visual.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var b in visual.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var b in visual.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(b);foreach(var a in visual.GetComponentsInChildren<Animator>(true))UnityEngine.Object.DestroyImmediate(a);
   var renderers=visual.GetComponentsInChildren<Renderer>(true);var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float scale=i<14?8/Mathf.Max(.01f,bounds.size.y):i<32?3/Mathf.Max(.01f,Mathf.Max(bounds.size.x,bounds.size.z)):1;visual.transform.localScale*=scale;visual.transform.localPosition-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z)*scale;
   if(i<14){var c=g.AddComponent<CapsuleCollider>();c.radius=.6f;c.height=6;c.center=Vector3.up*4;var body=g.AddComponent<Rigidbody>();body.mass=90;body.centerOfMass=Vector3.up*3;body.maxLinearVelocity=28;body.maxAngularVelocity=12;body.linearDamping=.08f;body.angularDamping=.3f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.solverIterations=16;var t=g.AddComponent<CheeseTree>();t.body=body;s.trees[i]=t;}else if(i<32){var c=g.AddComponent<SphereCollider>();c.radius=1.35f;c.center=Vector3.up*.65f;}else{var c=g.AddComponent<CapsuleCollider>();c.radius=.55f;c.height=2.2f;c.direction=2;c.center=Vector3.up*.6f;}
   g.transform.position=CheeseRules.Surface((i%8-3.5f)*10,45+i*4);g.SetActive(false);
  }
  var grassSource=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Grass_01.prefab");var sourceFilter=grassSource.GetComponentInChildren<MeshFilter>();var grass=new GameObject("Tall grass detail mesh",typeof(MeshFilter),typeof(MeshRenderer));grass.GetComponent<MeshFilter>().sharedMesh=sourceFilter.sharedMesh;grass.GetComponent<MeshRenderer>().sharedMaterial=Material("Tall grass",new Color(.29f,.48f,.12f));PrefabUtility.SaveAsPrefabAsset(grass,Root+"Prefabs/TallGrass.prefab");UnityEngine.Object.DestroyImmediate(grass);var data=s.terrain.terrainData;data.SetDetailResolution(128,8);data.SetDetailScatterMode(DetailScatterMode.InstanceCountMode);data.detailPrototypes=new[]{new DetailPrototype{prototype=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/TallGrass.prefab"),usePrototypeMesh=true,useInstancing=true,renderMode=DetailRenderMode.VertexLit,minHeight=1.8f,maxHeight=2.8f,minWidth=.9f,maxWidth=1.6f,noiseSpread=.3f,healthyColor=Color.white,dryColor=new Color(.8f,.85f,.5f)}};s.terrain.detailObjectDistance=85;s.terrain.detailObjectDensity=.7f;s.terrain.drawTreesAndFoliage=true;s.terrain.ignoreQualitySettings=true;data.RefreshPrototypes();data.SetDetailLayer(0,0,0,CheeseScenery.GrassMap(data.detailResolution,new System.Random(8137),out _));s.terrain.Flush();
 }
 static GameObject Animal(string name,string model,Color color,Texture texture){string path=Root+"Prefabs/Scenery"+name+".prefab";var source=AssetDatabase.LoadAssetAtPath<GameObject>(model);var original=UnityEngine.Object.Instantiate(source);var root=new GameObject("Authentic Malbers "+name);var material=Material("Scenery "+name,color,texture);int index=0;foreach(var renderer in original.GetComponentsInChildren<SkinnedMeshRenderer>(true)){if(renderer.name.IndexOf("fur",StringComparison.OrdinalIgnoreCase)>=0)continue;var mesh=new Mesh();renderer.BakeMesh(mesh);if(mesh.vertexCount==0){UnityEngine.Object.DestroyImmediate(mesh);continue;}string meshPath=Root+"Art/Animals/"+name+" pose "+index+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(existing==null){AssetDatabase.CreateAsset(mesh,meshPath);existing=mesh;}else{EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);}var g=new GameObject(renderer.name,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(root.transform,false);g.transform.SetPositionAndRotation(renderer.transform.position,renderer.transform.rotation);g.transform.localScale=renderer.transform.lossyScale;g.GetComponent<MeshFilter>().sharedMesh=existing;g.GetComponent<MeshRenderer>().sharedMaterial=material;Debug.Log("CHEESE_ANIMAL_MESH "+name+" "+renderer.name+" vertices="+existing.vertexCount);index++;}
  if(index==0)throw new Exception("Animal model has no skinned mesh "+model);var rs=root.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);float factor=2.8f/Mathf.Max(bounds.size.x,bounds.size.z);foreach(Transform child in root.transform){child.localPosition*=factor;child.localScale*=factor;}root.transform.position=new Vector3(-bounds.center.x*factor,-bounds.min.y*factor,-bounds.center.z*factor);var pivot=new GameObject(name+" scenery visual");root.transform.SetParent(pivot.transform,true);PrefabUtility.SaveAsPrefabAsset(pivot,path);UnityEngine.Object.DestroyImmediate(original);UnityEngine.Object.DestroyImmediate(pivot);return AssetDatabase.LoadAssetAtPath<GameObject>(path);
 }
}
}
